        StrMotion pMotion = GetMotion();
        if (pMotion != null) {
            switch (d) {
                case 1:
                    sp.Draw(pMotion.JX + fPosX, fPosY - pMotion.JY, pMotion.Motion, iSprIndex);
                    break;
                case 2:
                    sp.DrawFlip(fPosX - pMotion.JX, fPosY - pMotion.JY, pMotion.Motion, iSprIndex);
                    break;
            }
        }
    }

