package com.gpoqagggdg;

public class col {
    int iAX1;
    int iAX2;
    int iAY1;
    int iAY2;
    int Total_Frame = 0;
    int LoadAni = 0;
    int iATT = 0;
    private ArrayList<StrMain> m_MainList = new ArrayList<>();

    void Release() {
        for (int ii = 0; ii < this.m_MainList.size(); ii++) {
            this.m_MainList.remove(ii);
        }
        this.m_MainList.clear();
    }

    void ColLoad(int iRawIndex) {
        Release();
        String szRsc = FileIO.GetInstance().GetRawString(iRawIndex);
        if (szRsc.length() > 0) {
            int iCount = 0;
            int iTotalFrameCount = 0;
            int iLoadAniCount = 0;
            int iTempCount = 0;
            String[] szParset = szRsc.split(",");
            for (int i = 0; i < szParset.length; i++) {
                if (iCount == 0) {
                    this.Total_Frame = Integer.parseInt(szParset[i]);
                    iCount++;
                    for (int c = 0; c < this.Total_Frame; c++) {
                        this.m_MainList.add(new StrMain());
                    }
                } else if (iCount == 1) {
                    this.LoadAni = Integer.parseInt(szParset[i]);
                    iCount++;
                } else {
                    if (iTempCount == 0) {
                        iTempCount = 1;
                        if (iLoadAniCount < this.LoadAni) {
                            this.iATT = Integer.parseInt(szParset[i]);
                        }
                    } else if (iTempCount == 1) {
                        iTempCount = 2;
                        if (iLoadAniCount < this.LoadAni) {
                            this.iAX1 = Integer.parseInt(szParset[i]);
                        }
                    } else if (iTempCount == 2) {
                        iTempCount = 3;
                        if (iLoadAniCount < this.LoadAni) {
                            this.iAY1 = Integer.parseInt(szParset[i]);
                        }
                    } else if (iTempCount == 3) {
                        iTempCount = 4;
                        if (iLoadAniCount < this.LoadAni) {
                            this.iAX2 = Integer.parseInt(szParset[i]);
                        }
                    } else if (iTempCount == 4) {
                        if (iLoadAniCount < this.LoadAni) {
                            this.iAY2 = Integer.parseInt(szParset[i]);
                        }
                        if (this.iATT > 0) {
                            strCol pObject = new strCol();
                            pObject.Motion = iLoadAniCount;
                            pObject.SAVEATT = this.iATT;
                            pObject.ATT = this.iATT;
                            pObject.AX1 = this.iAX1;
                            pObject.AY1 = this.iAY1;
                            pObject.AX2 = this.iAX2;
                            pObject.AY2 = this.iAY2;
                            this.m_MainList.get(iTotalFrameCount).m_ColList.add(pObject);
                        }
                        iLoadAniCount++;
                        iTempCount = 0;
                    }
                    if (iLoadAniCount >= this.LoadAni) {
                        iLoadAniCount = 0;
                        iTotalFrameCount++;
                    }
                }
            }
        }
    }

    void Restore() {
        for (int i = 0; i < this.Total_Frame; i++) {
            for (int j = 0; j < this.LoadAni; j++) {
