    void Init(float x, float y, int iType, boolean bDir) {
        this.m_fX = x;
        this.m_fY = y;
        this.m_iType = iType;
        this.m_iAlpha = 255;
        this.m_bLife = true;
        this.m_bDir = bDir;
        this.m_fJX = 0.0f;
        this.m_fJY = 0.0f;
        this.m_iCount = 0;
        this.m_fZoom = 1.0d;
        if (iType == 1) {
            this._EffectAni.Add(R.drawable.pak0, 0, -13, -8, 0);
            this._EffectAni.Add(R.drawable.pak1, 1, -31, -38, 0);
            this._EffectAni.Add(R.drawable.pak2, 0, -37, -45, 0);
            this._EffectAni.Add(R.drawable.pak3, 1, -39, -63, 0);
            this._EffectAni.Init();
        }
        if (iType == 2) {
            this._EffectAni.Add(R.drawable.particle0, 0, -4, -3, 0);
            this._EffectAni.Add(R.drawable.particle1, 0, -5, -5, 0);
            this._EffectAni.Add(R.drawable.particle2, 0, -5, -5, 0);
            this._EffectAni.Add(R.drawable.particle3, 0, -3, -3, 0);
            this._EffectAni.Add(R.drawable.particle4, 0, -2, -2, 0);
            this._EffectAni.Add(R.drawable.particle5, 0, -1, -2, 0);
            this._EffectAni.Add(R.drawable.particle6, 0, -2, -2, 0);
            this._EffectAni.Add(R.drawable.particle7, 0, -2, -2, 0);
            this._EffectAni.Init();
            if (GameValue.GetInstance().GetProbabilty(0.5d)) {
                this.m_fJX = -(GameValue.GetInstance().GetRandom(4) + 1);
            } else {
                this.m_fJX = GameValue.GetInstance().GetRandom(4) + 1;
            }
            this.m_fJY = GameValue.GetInstance().GetRandom(4) + 4;
            this.m_iCount = GameValue.GetInstance().GetRandom(34) + 30;
        }
        if (iType == 3) {
            this._EffectAni.Add(R.drawable.guard0, 1, -15, -13, 0);
            this._EffectAni.Add(R.drawable.guard1, 1, -17, -15, 0);
            this._EffectAni.Add(R.drawable.guard2, 1, -17, -17, 0);
            this._EffectAni.Add(R.drawable.guard3, 1, -23, -17, 0);
            this._EffectAni.Add(R.drawable.guard4, 1, -23, -18, 0);
            this._EffectAni.Add(R.drawable.guard5, 1, -20, -18, 0);
            this._EffectAni.Init();
        }
        if (iType == 4) {
            this._EffectAni.Add(R.drawable.coin0, 4, -17, -42, 0);
            this._EffectAni.Add(R.drawable.coin1, 4, -26, -41, 0);
            this._EffectAni.Add(R.drawable.coin2, 4, -15, -41, 0);
            this._EffectAni.Add(R.drawable.coin3, 4, -3, -41, 0);
            this._EffectAni.Init();
            if (GameValue.GetInstance().GetProbabilty(0.5d)) {
                this.m_fJX = -(GameValue.GetInstance().GetRandom(4) + 1);
            } else {
                this.m_fJX = GameValue.GetInstance().GetRandom(4) + 1;
            }
            this.m_fJY = 10.0f;
            this.m_iCount = 0;
        }
    }

    void ProcEffect() {
        if (this.m_bLife) {
            if ((this.m_iType == 1 || this.m_iType == 3) && this._EffectAni.EndAni()) {
                this.m_bLife = false;
            }
            if (this.m_iType == 2) {
                this._EffectAni.doAni();
                this.m_fX += this.m_fJX;
                this.m_fY -= this.m_fJY;
                this.m_fJY = (float) (this.m_fJY - 0.5d);
                float f = this.m_fY;
                Player.getInstance();
                if (f > 310.0f) {
                    this.m_fJY = GameValue.GetInstance().GetRandom(4) + 4;
                }
                this.m_iCount--;
                if (this.m_iCount < 0) {
                    this.m_bLife = false;
                }
            }
            if (this.m_iType == 4) {
                this._EffectAni.doAni();
                if (this.m_fY >= GameMain.GetInstance().m_pUser.GetBadak() && this.m_fJY < 0.0f) {
                    this.m_fY = GameMain.GetInstance().m_pUser.GetBadak();
                } else {
                    this.m_fX += this.m_fJX;
                    this.m_fY -= this.m_fJY;
                    this.m_fJY = (float) (this.m_fJY - 0.5d);
                }
                this.m_iCount++;
                if (this.m_iCount > 300) {
                    this.m_bLife = false;
                }
                if (Define.GetInstance().HITCHECK(this.m_fX - 10.0f, this.m_fY - 40.0f, this.m_fX + 10.0f, this.m_fY, GameMain.GetInstance().m_pUser.m_fX - 15.0f, GameMain.GetInstance().m_pUser.m_fY - 60.0f, GameMain.GetInstance().m_pUser.m_fX + 15.0f, GameMain.GetInstance().m_pUser.m_fY) && this.m_fJY < 0.0f) {
                    this.m_bLife = false;
                    SoundManager.getInstance().PlaySound("COIN");
                    GameMain.GetInstance().m_iMyCoin++;
                }
            }
        }
    }

    void DrawEffect() {
        if (this.m_bLife) {
            this._EffectAni.DrawSpr(this.m_fX, this.m_fY, false);
        }
    }
