package com.gpoqagggdg;

    void ProcEffect() {
        if (this.m_bLife) {
            if ((this.m_iType == 1 || this.m_iType == 3) && this._EffectAni.EndAni()) {
                this.m_bLife = false;
            }
            if (this.m_iType == 2) {
                this._EffectAni.doAni();
                this.m_fX += this.m_fJX;
                this.m_fY -= this.m_fJY;
                this.m_fJY = (float) (this.m_fJY - 0.5d);
                float f = this.m_fY;
                Player.getInstance();
                if (f > 310.0f) {
                    this.m_fJY = GameValue.GetInstance().GetRandom(4) + 4;
                }
                this.m_iCount--;
                if (this.m_iCount < 0) {
                    this.m_bLife = false;
                }
            }
            if (this.m_iType == 4) {
                this._EffectAni.doAni();
                if (this.m_fY >= GameMain.GetInstance().m_pUser.GetBadak() && this.m_fJY < 0.0f) {
                    this.m_fY = GameMain.GetInstance().m_pUser.GetBadak();
                } else {
                    this.m_fX += this.m_fJX;
                    this.m_fY -= this.m_fJY;
                    this.m_fJY = (float) (this.m_fJY - 0.5d);
                }
                this.m_iCount++;
                if (this.m_iCount > 300) {
                    this.m_bLife = false;
                }
                if (Define.GetInstance().HITCHECK(this.m_fX - 10.0f, this.m_fY - 40.0f, this.m_fX + 10.0f, this.m_fY, GameMain.GetInstance().m_pUser.m_fX - 15.0f, GameMain.GetInstance().m_pUser.m_fY - 60.0f, GameMain.GetInstance().m_pUser.m_fX + 15.0f, GameMain.GetInstance().m_pUser.m_fY) && this.m_fJY < 0.0f) {
                    this.m_bLife = false;
                    SoundManager.getInstance().PlaySound("COIN");
                    GameMain.GetInstance().m_iMyCoin++;
                }
            }
        }
    }

