    boolean CheckCrash(int ix1, int iy1, int ix2, int iy2, int iAttackType, int power) {
        if (this.m_iAction == 12 || this.m_iAction == 20) {
            return false;
        }
        int ikx = this._StandAni.GetWidth() / 2;
        int iky = this._StandAni.GetHeight();
        if (Define.GetInstance().HITCHECK(ix1, iy1, ix2, iy2, this.m_fX - ikx, this.m_fY - iky, this.m_fX + ikx, this.m_fY) && this.m_bDamageFlag) {
            this.m_iHP -= power;
            GameMain.GetInstance().AddCombo();
            GameMain.GetInstance().AddScore(power);
            this.m_bHPView = true;
            this.m_iState = 1;
            this.m_bDamageFlag = false;
            this.m_bDir = false;
            if (GameMain.GetInstance().m_pUser.GetDir() == 1) {
                this.m_bDir = true;
            }
            String[] szText = {"DAMAGE1", "DAMAGE2", "DAMAGE3", "DAMAGE4"};
            SoundManager.getInstance().PlaySound(szText[GameValue.GetInstance().GetRandom(4)]);
            if (this.m_iType <= 4) {
                String[] szText2 = {"WOMAN_UK01", "WOMAN_UK02", "WOMAN_UK03", "WOMAN_UK04"};
                SoundManager.getInstance().PlaySound(szText2[GameValue.GetInstance().GetRandom(4)]);
            }
            if (this.m_iType == 15) {
                String[] szText22 = {"GOUKI_UK01", "GOUKI_UK02", "GOUKI_UK03"};
                SoundManager.getInstance().PlaySound(szText22[GameValue.GetInstance().GetRandom(3)]);
            }
            ResetAction();
            if (iAttackType == 1) {
                SetHitTime();
                Player.getInstance().SetHitTime();
                SetAction(9);
            }
            if (iAttackType == 2) {
                SetHitTime();
                Player.getInstance().SetHitTime();
                SetAction(10);
            }
            if (iAttackType == 3) {
                SetHitTime();
                Player.getInstance().SetHitTime();
                SetAction(14);
            }
            if (iAttackType == 4) {
                SetHitTime();
                Player.getInstance().SetHitTime();
                SetAction(15);
            }
            int ix = (GameValue.GetInstance().GetRandom(this._StandAni.GetWidth() * 2) + ((int) this.m_fX)) - (this._StandAni.GetWidth() / 2);
            int iy = (GameValue.GetInstance().GetRandom(this._StandAni.GetHeight()) + ((int) this.m_fY)) - this._StandAni.GetHeight();
            EffectManager.GetInstance().AddEffect(1, ix, iy, false);
            for (int ii = 0; ii < 5; ii++) {
                int ix3 = (GameValue.GetInstance().GetRandom(this._StandAni.GetWidth() * 2) + ((int) this.m_fX)) - (this._StandAni.GetWidth() / 2);
                int iy3 = (GameValue.GetInstance().GetRandom(this._StandAni.GetHeight()) + ((int) this.m_fY)) - this._StandAni.GetHeight();
                EffectManager.GetInstance().AddEffect(2, ix3, iy3, false);
            }
            return true;
        }
        return false;
    }

