    void SetHitTime() {
        this.m_bHitTime = true;
        this.m_lHitTime = System.currentTimeMillis();
    }

    boolean ProcHitTime() {
        if (!this.m_bHitTime) {
            return false;
        }
        long lNow = System.currentTimeMillis();
        if (lNow - this.m_lHitTime >= 100) {
            this.m_bHitTime = false;
        }
        return true;
    }

    void ResetAction() {
        this._JumpAni.Clear();
        this._Attack1Ani.Clear();
        this._Attack2Ani.Clear();
        this._Attack3Ani.Clear();
        this._Attack4Ani.Clear();
        this._JumpPunchAni.Clear();
        this._JumpKickAni.Clear();
        this._Damage1Ani.Clear();
        this._Damage2Ani.Clear();
        this._NoopkiAni.Clear();
        this._StandUpAni.Clear();
        this.m_iAction = 1;
    }

    void SetAction(int itype) {
        this.m_iAction = itype;
        if (itype == 2) {
            this.m_lMoveTime = System.currentTimeMillis();
            this.m_lMoveDelay = GameValue.GetInstance().GetRandom(2000) + 2000;
            if (!this.m_bDir) {
                if (GameValue.GetInstance().GetProbabilty(0.7d)) {
                    this.m_fJX = 2;
                } else {
                    this.m_fJX = -2;
                }
            } else if (GameValue.GetInstance().GetProbabilty(0.7d)) {
                this.m_fJX = -2;
            } else {
                this.m_fJX = 2;
            }
        }
        if (itype == 3) {
            if (this.m_fX > GameMain.GetInstance().m_pUser.m_fX) {
                this.m_bDir = true;
            } else {
                this.m_bDir = false;
            }
            this.m_lMoveTime = System.currentTimeMillis();
            this.m_lMoveDelay = GameValue.GetInstance().GetRandom(1000) + 1500;
            if (!this.m_bDir) {
                this.m_fJX = 4;
            } else {
                this.m_fJX = -4;
            }
        }
        if (itype == 5) {
            this.m_fJX = 10.0f;
        }
        if (itype == 6) {
            this.m_fJX = 2.0f;
            this.m_fJY = 7.0f;
            if (this.m_iType == 4) {
                this.m_fJY = 10.0f;
            }
            if (this.m_iType == 15) {
                this.m_fJX = 5.0f;
                this.m_fJY = 8.0f;
            }
            if (this.m_iType == 14) {
                this.m_fJY = 12.0f;
            }
        }
        if (itype == 7) {
            this.m_fJX = 10.0f;
        }
        if (itype == 9) {
            float f = this.m_fY;
            Player.getInstance();
            if (f < 310.0f) {
                this.m_iAction = 10;
                this.m_fJY = 5.0f;
            }
        }
        if (itype == 10) {
            this.m_fJY = 5.0f;
        }
        if (itype == 14) {
            this.m_fJY = 4.0f;
        }
        if (itype == 15) {
            this.m_fJY = -6.0f;
        }
        if (itype == 16) {
            this.m_fJY = 11.0f;
        }
        if (itype == 11) {
            SoundManager.getInstance().PlaySound("KOONG");
            this.m_fJY = 3.0f;
        }
    }

    int GetDistance() {
        int iDistance = Math.abs(((int) GameMain.GetInstance().m_pUser.m_fX) - ((int) this.m_fX));
        return iDistance;
    }

    void ProcMoveRandom() {
        int iDistance = GetDistance();
        if (this.m_iAction <= 3 && this.m_iState == 1) {
            if (this.m_iType == 1) {
                if (iDistance < 80) {
                    if (this.m_iAction == 3) {
                        SetAction(5);
                    } else if (GameValue.GetInstance().GetRandom(50) == 4) {
                        SetAction(4);
                    }
                }
            } else if (this.m_iType == 2) {
                if (iDistance < 80) {
                    if (this.m_iAction == 3) {
                        SetAction(5);
                    } else if (GameValue.GetInstance().GetRandom(50) == 4) {
                        if (GameValue.GetInstance().GetProbabilty(0.5d)) {
                            SetAction(4);
                        } else {
