            int iRandomValue = 100;
            if (this.m_iType >= 11) {
                iRandomValue = 50;
            }
            this.m_iMoveRandom = GameValue.GetInstance().GetRandom(iRandomValue);
            if (this.m_iMoveRandom == 4) {
                ResetAction();
                if (this.m_iType == 4 || this.m_iType == 11 || this.m_iType == 12 || this.m_iType == 13) {
