package com.gpoqagggdg;

    void GameDraw() {
        Define.GetInstance().SetResize();
        if (this.m_bPause) {
            PutText(400.0f, 240.0f, "GAME PAUSE", 30, true);
            PutText(400.0f, 280.0f, "点击继续游戏", 30, true);
        }
        switch (m_iGameState) {
            case 0:
                Define.GetInstance().canvas.drawColor(-16777216);
                Define.GetInstance().PutText(MAX_HP, 240, "读取中...", 40, -1, true);
                break;
            case 1:
                Define.GetInstance().canvas.drawColor(-16777216);
                Sprite.GetInstance().PutSprite(400.0f, 240.0f, R.drawable.arixteam, this.m_iLogoAlpha, false, true, false, true);
                break;
            case 2:
                Sprite.GetInstance().PutScreenSize2(0.0f, 0.0f, this.m_iTitleBgX, 255);
                Sprite.GetInstance().PutSprite(400.0f, 180.0f, R.drawable.title, 255, false, true, false, true);
                PutText(400.0f, 430.0f, "ORIGINAL DESIGNED BY CAPCOM", 25, true);
                PutText(400.0f, 460.0f, "PRESENTED BY ARIXTEAM 2011", 25, true);
                this.m_pUser.PutUser();
                this.m_pEnemy.PutUser();
                this.m_pUser.PutJang();
                this.m_pEnemy.PutJang();
                EffectManager.GetInstance().DrawEffect();
                PutTitle();
                break;
            case 4:
                BackGround.GetInstance().PutBackGround();
                DrawGo();
                DrawCombo();
                GameValue.GetInstance().paint.setColorFilter(GameValue.GetInstance().DarkGrayFilter);
                Define.GetInstance().canvas.drawRect(0.0f, Define.GetInstance().GetScreenY() - 100.0f, Define.GetInstance().GetScreenX(), Define.GetInstance().GetScreenY(), GameValue.GetInstance().paint);
                EnemyManager.GetInstance().DrawEnemy();
                Player.getInstance().PutPlayer();
                EnemyMissileManager.GetInstance().DrawEnemyMissile();
                MissileManager.GetInstance().DrawMissile();
                EffectManager.GetInstance().DrawEffect();
                Player.getInstance().PutKey();
                GameValue.GetInstance().paint.setColorFilter(GameValue.GetInstance().DarkGrayFilter);
                Define.GetInstance().PutText(401, 101, "得分 : " + this.m_iGameScore, 25, -1, false);
                GameValue.GetInstance().paint.setColorFilter(GameValue.GetInstance().WhiteFilter);
                Define.GetInstance().PutText(MAX_HP, 100, "得分 : " + this.m_iGameScore, 25, -1, false);
                GameValue.GetInstance().paint.setColorFilter(GameValue.GetInstance().DarkGrayFilter);
                Define.GetInstance().PutText(251, 101, "x " + this.m_iPlayerLife, 25, -1, false);
                GameValue.GetInstance().paint.setColorFilter(GameValue.GetInstance().WhiteFilter);
                Define.GetInstance().PutText(_DIFFICULT_EASY, 100, "x " + this.m_iPlayerLife, 25, -1, false);
                DrawRound();
                if (this.m_bGameOver) {
                    Sprite.GetInstance().PutSprite(400.0f, 240.0f, R.drawable.gameover, 255, false, true, false, true);
                }
                DrawFade();
                break;
            case 5:
                Define.GetInstance().canvas.drawColor(-16777216);
                this.m_pUser.PutUser();
                this.m_pEnemy.PutUser();
                this.m_pUser.PutJang();
                this.m_pEnemy.PutJang();
                EffectManager.GetInstance().DrawEffect();
                for (int ii = 0; ii < this.szEnding.length; ii++) {
                    PutText(400.0f, (ii * 35) + this.m_fEndingY, this.szEnding[ii], 30, true);
                }
                break;
            case 6:
                PutSelect();
                break;
            case 7:
                PutStart();
                break;
            case 8:
                PutGameWorld();
                EffectManager.GetInstance().DrawEffect();
                break;
            case 9:
                PutWinner();
                break;
        }
    }

