    void PutComboCountNumber(float x, float y, int inum) {
        String chScore = Integer.toString(inum);
        byte[] t = chScore.getBytes();
        int[] iNumSpr = {R.drawable.combo0, R.drawable.combo1, R.drawable.combo2, R.drawable.combo3, R.drawable.combo4, R.drawable.combo5, R.drawable.combo6, R.drawable.combo7, R.drawable.combo8, R.drawable.combo9};
        for (int i = 0; i < chScore.length(); i++) {
            String a = new String(t, i, 1);
            Drawable img = GameView.mContext.getResources().getDrawable(iNumSpr[Integer.parseInt(a)]);
            img.setBounds(((int) x) + (i * 35), (int) y, (int) ((i * 35) + x + 35), (int) (_DIFFICULT_HARD + y));
            img.draw(Define.GetInstance().canvas);
        }
    }

    void AddCombo() {
        this.m_iComboCount++;
        this.m_lComboTime = System.currentTimeMillis();
        if (!this.m_bComboFlag) {
            this.m_fComboX = -100.0f;
            this.m_fComboJX = 10.0f;
            this.m_bComboFlag = true;
        }
    }

    void ProcCombo() {
        if (this.m_bComboFlag) {
            if (System.currentTimeMillis() - this.m_lComboTime >= 3000) {
                this.m_iComboCount = 0;
                this.m_bComboFlag = false;
            }
            if (this.m_fComboJX > 0.0f) {
                this.m_fComboX += this.m_fComboJX;
                this.m_fComboJX = (float) (this.m_fComboJX - 0.5d);
                if (this.m_fComboJX < 0.0f) {
                    this.m_fComboJX = 0.0f;
                }
            }
        }
    }

    void DrawCombo() {
        if (this.m_bComboFlag) {
            Sprite.GetInstance().PutSprite(this.m_fComboX, 140.0f, R.drawable.combo, 255, false, false, false, false);
            PutComboCountNumber(this.m_fComboX + 150.0f, 140.0f, this.m_iComboCount);
        }
    }

    void InitGo() {
        this.m_bGoFlag = true;
        this.m_iGoCount = 0;
        this.m_lGoTime = System.currentTimeMillis();
    }

    void ProcGo() {
        if (this.m_bGoFlag) {
            if (System.currentTimeMillis() - this.m_lGoTime >= 500) {
                this.m_lGoTime = System.currentTimeMillis();
                this.m_iGoCount++;
                SoundManager.getInstance().PlaySound("GO");
            }
            if (this.m_iGoCount > 5) {
                this.m_bGoFlag = false;
            }
        }
    }

    void DrawGo() {
        if (this.m_bGoFlag && this.m_iGoCount % 2 == 1) {
            Sprite.GetInstance().PutSprite(650.0f, 200.0f, R.drawable.go, 255, false, true, false, true);
        }
    }

