                break;
            case 1:
                Define.GetInstance().canvas.drawColor(-16777216);
                Sprite.GetInstance().PutSprite(400.0f, 240.0f, R.drawable.arixteam, this.m_iLogoAlpha, false, true, false, true);
                break;
            case 2:
                Sprite.GetInstance().PutScreenSize2(0.0f, 0.0f, this.m_iTitleBgX, 255);
                Sprite.GetInstance().PutSprite(400.0f, 180.0f, R.drawable.title, 255, false, true, false, true);
