                        this.m_iDifficult = 15;
                    } else if (this.m_iDifficult == 15) {
                        this.m_iDifficult = _DIFFICULT_EASY;
                    }
                }
                if (KeyCommand.GetInstance().mouse_button(0, 174, iX2, 202)) {
                    if (MusicPlayer.getInstance().g_iBGM == 1) {
                        MusicPlayer.getInstance().g_iBGM = 0;
                    } else {
                        MusicPlayer.getInstance().g_iBGM = 1;
                    }
                }
                if (KeyCommand.GetInstance().mouse_button(0, 215, iX2, 241)) {
                    if (SoundManager.getInstance().g_iSOUNDFLAG == 1) {
                        SoundManager.getInstance().g_iSOUNDFLAG = 0;
                    } else {
                        SoundManager.getInstance().g_iSOUNDFLAG = 1;
                    }
                }
                if (KeyCommand.GetInstance().mouse_button(0, 334, iX2, 363)) {
                    InitMenuSpeed();
                    this.m_iMenuOrder = 1;
                    break;
                }
                break;
            case 4:
                int iX3 = (int) Define.GetInstance().GetScreenX();
                ProcMenuSpeed();
                if (KeyCommand.GetInstance().mouse_button(0, 334, iX3, 363)) {
                    InitMenuSpeed();
                    this.m_iMenuOrder = 1;
                    break;
                }
                break;
            case 5:
                if (KeyCommand.GetInstance().mouse_button(328, 256, 392, 292)) {
                    this.m_iGameMode = 1;
                    this.m_bContinue = true;
                    InitSelect();
                }
                if (KeyCommand.GetInstance().mouse_button(413, 256, 460, 292)) {
                    this.m_iGameMode = 1;
                    this.m_bContinue = false;
                    InitSelect();
                    break;
                }
                break;
        }
    }

