    void ProcSelect() {
        boolean bSelect = false;
        if (KeyCommand.GetInstance().mouse_button(240, 168, 311, 239)) {
            this.m_iSelectCharacter = 10;
        }
        if (KeyCommand.GetInstance().mouse_button(322, 172, 393, 243)) {
            this.m_iSelectCharacter = 0;
        }
        if (KeyCommand.GetInstance().mouse_button(406, 172, 477, 244)) {
            this.m_iSelectCharacter = 1;
        }
        if (KeyCommand.GetInstance().mouse_button(487, 168, 559, 240)) {
            this.m_iSelectCharacter = 11;
        }
        if (KeyCommand.GetInstance().mouse_button(232, _DIFFICULT_EASY, 307, 327)) {
            this.m_iSelectCharacter = 2;
        }
        if (KeyCommand.GetInstance().mouse_button(318, 254, 393, 332)) {
            this.m_iSelectCharacter = 3;
        }
        if (KeyCommand.GetInstance().mouse_button(406, 254, 481, 332)) {
            this.m_iSelectCharacter = 4;
        }
        if (KeyCommand.GetInstance().mouse_button(492, _DIFFICULT_EASY, 568, 328)) {
            this.m_iSelectCharacter = 5;
        }
        if (KeyCommand.GetInstance().mouse_button(215, 338, 300, 422)) {
            this.m_iSelectCharacter = 6;
        }
        if (KeyCommand.GetInstance().mouse_button(Player.m_iLimitY, 342, 393, 425)) {
            this.m_iSelectCharacter = 7;
        }
        if (KeyCommand.GetInstance().mouse_button(406, 342, 489, 425)) {
            this.m_iSelectCharacter = 8;
        }
        if (KeyCommand.GetInstance().mouse_button(500, 338, 583, 422)) {
            this.m_iSelectCharacter = 9;
        }
        if (KeyCommand.GetInstance().mouse_button(286, 430, 550, 480)) {
            bSelect = true;
        }
        if (bSelect) {
            this.m_pUser.InitUser(0, this.m_iSelectCharacter);
            if (this.m_iGameMode == 1) {
                ResetGame();
                GetInstance().SetGameState("STATE_GAME");
                if (this.m_bContinue) {
                    BackGround.GetInstance().SetStage(BackGround.GetInstance().m_iContinueStage);
                    this.m_iPlayerLife = this.m_iPlayerContinueLife;
                } else {
                    BackGround.GetInstance().SetStage(0);
                }
                BackGround.GetInstance().SetEnemy();
                GetInstance().InitFade(1);
                return;
            }
            BackGround.GetInstance().m_iStage = 1;
            for (int ii = 0; ii < 8; ii++) {
                this.m_iCharacter[ii] = -1;
            }
            int iAdd = 0;
            while (iAdd < 8) {
                boolean bEqul = false;
                int iCharacter = GameValue.GetInstance().GetRandom(12);
                for (int ic = 0; ic < 8; ic++) {
                    if (iCharacter == this.m_iCharacter[ic] || iCharacter == this.m_iSelectCharacter) {
                        bEqul = true;
                    }
                }
                if (!bEqul) {
                    this.m_iCharacter[iAdd] = iCharacter;
                    iAdd++;
                }
            }
            if (this.m_bPractice) {
                InitGame();
            } else {
                InitStart();
            }
        }
    }

