package com.gpoqagggdg;

    void ProcTitle() {
        switch (this.m_iMenuOrder) {
            case 0:
                if (KeyCommand.GetInstance().mouse_button(0, 0, (int) Define.GetInstance().GetScreenX(), (int) Define.GetInstance().GetScreenY())) {
                    this.m_iMenuOrder = 1;
                    break;
                }
                break;
            case 1:
                ProcMenuSpeed();
                int iX = (int) Define.GetInstance().GetScreenX();
                if (KeyCommand.GetInstance().mouse_button(0, 133, iX, 163)) {
                    if (BackGround.GetInstance().m_iContinueStage > -1) {
                        this.m_iMenuOrder = 5;
                    } else {
                        this.m_iGameMode = 1;
                        this.m_bContinue = false;
                        InitSelect();
                    }
                }
                if (KeyCommand.GetInstance().mouse_button(0, 174, iX, 202)) {
                    this.m_iGameMode = 2;
                    this.m_bPractice = false;
                    InitSelect();
                }
                if (KeyCommand.GetInstance().mouse_button(0, 215, iX, 241)) {
                    InitMenuSpeed();
                    this.m_iMenuOrder = 2;
                }
                if (KeyCommand.GetInstance().mouse_button(0, 254, iX, 282)) {
                    this.m_iGameMode = 2;
                    this.m_bPractice = true;
                    InitSelect();
                }
                if (KeyCommand.GetInstance().mouse_button(0, 293, iX, 322)) {
                    InitMenuSpeed();
                    this.m_iMenuOrder = 4;
                }
                if (KeyCommand.GetInstance().mouse_button(0, 334, iX, 363)) {
                    SoundManager.getInstance().Release();
                    MusicPlayer.getInstance().Release();
                    System.exit(0);
                    break;
                }
                break;
            case 2:
                int iX2 = (int) Define.GetInstance().GetScreenX();
                ProcMenuSpeed();
                if (KeyCommand.GetInstance().mouse_button(0, 133, iX2, 163)) {
                    if (this.m_iDifficult == _DIFFICULT_EASY) {
                        this.m_iDifficult = _DIFFICULT_NORMAL;
                    } else if (this.m_iDifficult == _DIFFICULT_NORMAL) {
                        this.m_iDifficult = _DIFFICULT_HARD;
                    } else if (this.m_iDifficult == _DIFFICULT_HARD) {
                        this.m_iDifficult = 15;
                    } else if (this.m_iDifficult == 15) {
                        this.m_iDifficult = _DIFFICULT_EASY;
                    }
                }
                if (KeyCommand.GetInstance().mouse_button(0, 174, iX2, 202)) {
                    if (MusicPlayer.getInstance().g_iBGM == 1) {
                        MusicPlayer.getInstance().g_iBGM = 0;
                    } else {
                        MusicPlayer.getInstance().g_iBGM = 1;
                    }
                }
                if (KeyCommand.GetInstance().mouse_button(0, 215, iX2, 241)) {
                    if (SoundManager.getInstance().g_iSOUNDFLAG == 1) {
                        SoundManager.getInstance().g_iSOUNDFLAG = 0;
                    } else {
                        SoundManager.getInstance().g_iSOUNDFLAG = 1;
                    }
                }
                if (KeyCommand.GetInstance().mouse_button(0, 334, iX2, 363)) {
                    InitMenuSpeed();
                    this.m_iMenuOrder = 1;
                    break;
                }
                break;
            case 4:
                int iX3 = (int) Define.GetInstance().GetScreenX();
                ProcMenuSpeed();
                if (KeyCommand.GetInstance().mouse_button(0, 334, iX3, 363)) {
                    InitMenuSpeed();
                    this.m_iMenuOrder = 1;
                    break;
                }
                break;
            case 5:
                if (KeyCommand.GetInstance().mouse_button(328, 256, 392, 292)) {
                    this.m_iGameMode = 1;
                    this.m_bContinue = true;
                    InitSelect();
                }
                if (KeyCommand.GetInstance().mouse_button(413, 256, 460, 292)) {
                    this.m_iGameMode = 1;
                    this.m_bContinue = false;
                    InitSelect();
                    break;
                }
                break;
        }
    }

