        if (GameMain.GetInstance().m_pUser.m_cDamageType < 2 && GameMain.GetInstance().m_pUser.m_iLifeTime <= 0 && Define.GetInstance().HITCHECK(ix1, iy1, ix2, iy2, GameMain.GetInstance().m_pUser.m_fX - 30.0f, GameMain.GetInstance().m_pUser.m_fY - 70.0f, GameMain.GetInstance().m_pUser.m_fX + 30.0f, GameMain.GetInstance().m_pUser.m_fY)) {
            GameMain.GetInstance().m_pUser.SetDir(1);
            this.m_bDir = false;
            if (!bDir) {
                GameMain.GetInstance().m_pUser.SetDir(2);
            }
            this.m_iDamageCount++;
            GameMain.GetInstance().m_fPlayerHP -= ipower;
            if (this.m_iDamageCount > 7) {
                this.m_iDamageCount = 0;
                iAttackType = 1;
            }
            GameMain.GetInstance().m_pUser.SetDamage(iAttackType, GameMain.GetInstance().m_pUser.GetDir(), 0.0f);
            return true;
        }
        return false;
    }

