    void ProcJump() {
        if (this.m_cJumpFlag != 0) {
            if (this.m_iAttackType == 0) {
                if (CheckButton(0, 597, 307, 676, 390) || CheckButton(1, 597, 307, 676, 390) || CheckButton(0, 597, 396, 676, 479) || CheckButton(1, 597, 396, 676, 479)) {
