                if (CheckButton(0, 684, 307, 763, 390) || CheckButton(1, 684, 307, 763, 390) || CheckButton(0, 684, 396, 763, 479) || CheckButton(1, 684, 396, 763, 479)) {
                    SoundManager.getInstance().PlaySound("BARAM");
                    ResetAction();
                    this.m_iAttackType = 2;
                }
            }
            AddPY(-this.m_fJY);
            this.m_fJY = (float) (this.m_fJY - 0.5d);
            if (GetPY() > Define.GetInstance().GetScreenPosY(310.0f)) {
                SetPY(310.0f);
                SoundManager.getInstance().PlaySound("BADAK");
                this.m_cJumpFlag = (char) 0;
                ResetAction();
                SetAction(0);
            }
            if (this.m_cJumpFlag == 2) {
                this.m_fSpeed = 2.5f;
                AddPX(-this.m_fSpeed);
            }
            if (this.m_cJumpFlag == 3) {
                this.m_fSpeed = 2.5f;
                AddPX(this.m_fSpeed);
            }
            if (this.m_cJumpFlag == 4) {
                this.m_fSpeed = 5.0f;
                AddPX(-this.m_fSpeed);
            }
            if (this.m_cJumpFlag == 5) {
                this.m_fSpeed = 5.0f;
                AddPX(this.m_fSpeed);
            }
        }
