    void ProcCheckAttack(Animation pAni, int ipower) {
        int ix1;
        int iy1;
        int ix2;
        int iy2;
        int iAttackType = pAni.GetAttack().intValue();
        if (iAttackType > 0) {
            if (pAni.GetNowDelay() == 0) {
                EnemyManager.GetInstance().SetDamageFlag();
            }
            if (!this.m_bDir) {
                ix1 = ((int) this.m_fPX) + pAni.GetJX().intValue();
                iy1 = ((int) this.m_fPY) - pAni.GetHeight();
                ix2 = ((int) this.m_fPX) + pAni.GetWidth() + pAni.GetJX().intValue();
                iy2 = (int) this.m_fPY;
            } else {
                ix1 = (((int) this.m_fPX) - pAni.GetWidth()) - pAni.GetJX().intValue();
                iy1 = ((int) this.m_fPY) - pAni.GetHeight();
                ix2 = ((int) this.m_fPX) - pAni.GetJX().intValue();
                iy2 = (int) this.m_fPY;
            }
            EnemyManager.GetInstance().CheckEnemy(ix1, iy1, ix2, iy2, iAttackType, ipower);
        }
    }

    void ProcPlayer() {
        if (BackGround.GetInstance().m_iStage == 3 && BackGround.GetInstance().m_bScrollFlag) {
            if (GameMain.GetInstance().m_pUser.m_fX < 168.0f) {
                GameMain.GetInstance().m_pUser.m_fX = 168.0f;
            }
            if (GameMain.GetInstance().m_pUser.m_fX > 670.0f) {
                GameMain.GetInstance().m_pUser.m_fX = 670.0f;
            }
        } else {
            if (GameMain.GetInstance().m_pUser.m_fX < 0.0f) {
                GameMain.GetInstance().m_pUser.m_fX = 0.0f;
            }
            if (GameMain.GetInstance().m_pUser.m_fX > Define.GetInstance().GetScreenX()) {
                GameMain.GetInstance().m_pUser.m_fX = Define.GetInstance().GetScreenX();
            }
        }
        if (this.m_iLife == 2) {
            if (System.currentTimeMillis() - this.m_lFlashTime >= 100) {
                this.m_lFlashTime = System.currentTimeMillis();
                this.m_iFlashCount++;
            }
            if (this.m_iFlashCount > 20) {
                this.m_iLife = 1;
            }
        }
        if (this.m_iHP <= 0 && this.m_iLife == 1) {
            String[] szText2 = {"UK01", "UK02", "UK03"};
            SoundManager.getInstance().PlaySound(szText2[GameValue.GetInstance().GetRandom(3)]);
            GameMain.GetInstance().m_pUser.SetDamage(2, GameMain.GetInstance().m_pUser.GetDir(), 0.0f);
        }
        GameMain.GetInstance().m_pUser.ProcUser();
    }

    void PutPlayer() {
        if (this.m_iLife != 2 || this.m_iFlashCount % 2 != 1) {
            GameMain.GetInstance().m_pUser.PutUser();
            GameMain.GetInstance().m_pUser.PutJang();
        }
    }

