                    SetJumpPower(this.m_fTempJumpPower, this.m_fTempGravity, 2);
                }
            }
            if (!this.m_bAttackFlag && !this.m_bJumpFlag) {
                if (KeyCommand.GetInstance().AKey() || KeyCommand.GetInstance().CKey()) {
                    this.m_iAniNumber = 12;
                    GetDashPower(0);
