            if (!this.m_bJumpFlag && !this.m_bAttackFlag && !KeyCommand.GetInstance().RTKey() && !KeyCommand.GetInstance().LTKey() && !KeyCommand.GetInstance().DNKey() && !KeyCommand.GetInstance().UPKey()) {
