    void ProcDamage() {
        if (this.m_bDamageFlag) {
            switch (this.m_cDamageType) {
                case 0:
                    if (GetDir() == 1) {
                        AddX(-3.0f);
                    } else {
                        AddX(3.0f);
                    }
                    if (this._PlayerAni._end_motion(this.m_iAniNumber)) {
                        ClearFlag();
                        break;
                    }
                    break;
                case 1:
                    if (GetDir() == 1) {
                        AddX(-3.0f);
                    } else {
                        AddX(3.0f);
                    }
                    this.m_fY -= this.m_fJump;
                    this.m_fJump -= this.m_fGravity;
                    if (this.m_fY > GetBadak()) {
                        this.m_fY = GetBadak();
                        SetDamage(2, GetDir(), 0.0f);
                    }
                    this._PlayerAni._end_motion(this.m_iAniNumber);
                    break;
                case 2:
                    if (GetDir() == 1) {
                        AddX(-2.0f);
                    } else {
                        AddX(2.0f);
                    }
                    this.m_fY -= this.m_fJump;
                    this.m_fJump -= this.m_fGravity;
                    if (this.m_fY > GetBadak()) {
                        this.m_fY = GetBadak();
                        SetDamage(3, GetDir(), 0.0f);
                    }
                    this._PlayerAni._end_motion(this.m_iAniNumber);
                    break;
                case 3:
                    if (this._PlayerAni._end_motion(this.m_iAniNumber)) {
                        if (GameMain.GetInstance().m_iGameMode != 1) {
                            int i = GameMain.GetInstance().m_iGameView;
                            GameMain.GetInstance();
                            if (i < 4) {
                                SetDamage(4, GetDir(), 0.0f);
                                break;
                            } else {
                                GetPlayerType();
                                break;
                            }
                        } else if (GameMain.GetInstance().m_fPlayerHP > 0.0f) {
                            SetDamage(4, GetDir(), 0.0f);
                            break;
                        } else if (GameMain.GetInstance().m_iPlayerLife > 0) {
                            GameTimer.GetInstance().InitFrame(50L);
                            GameMain.GetInstance().m_iPlayerLife--;
                            GameMain.GetInstance().m_fPlayerHP = 400.0f;
                            this.m_iLifeTime = 50;
                            SetDamage(4, GetDir(), 0.0f);
                            EnemyManager.GetInstance().SetDamage2();
                            break;
                        } else if (!GameMain.GetInstance().m_bGameOver) {
                            GameMain.GetInstance().m_bGameOver = true;
                            SoundManager.getInstance().PlaySound("GAMEOVER");
                            break;
                        }
                    }
                    break;
                case 4:
                    if (this._PlayerAni._end_motion(this.m_iAniNumber)) {
                        if (GameMain.GetInstance().m_iGameMode == 1) {
                            this.m_iLifeTime = 50;
                        } else if (GameMain.GetInstance().m_iDifficult != 250 && !GameMain.GetInstance().m_bPractice && GetPlayerType() == 1) {
                            this.m_iLifeTime = 50;
                        }
                        ClearFlag();
                        break;
                    }
                    break;
            }
        }
    }

    void CheckEnemy() {
        int AttackX1;
        int AttackX2;
        int AttackY1;
        int AttackY2;
        if (GameMain.GetInstance().m_iGameMode != 2) {
            int iAni = this.m_iAniNumber;
            int iNowMotion = this._PlayerAni.GetNow_Motion();
            if (GetDir() == 1) {
                AttackX1 = ((int) this.m_fX) + this._PlayerCol.GetAX1(iAni, iNowMotion);
                AttackX2 = ((int) this.m_fX) + this._PlayerCol.GetAX2(iAni, iNowMotion);
                AttackY1 = ((int) this.m_fY) + this._PlayerCol.GetAY1(iAni, iNowMotion);
                AttackY2 = ((int) this.m_fY) + this._PlayerCol.GetAY2(iAni, iNowMotion);
            } else {
                AttackX1 = ((int) this.m_fX) - this._PlayerCol.GetAX2(iAni, iNowMotion);
                AttackX2 = ((int) this.m_fX) - this._PlayerCol.GetAX1(iAni, iNowMotion);
                AttackY1 = ((int) this.m_fY) + this._PlayerCol.GetAY1(iAni, iNowMotion);
                AttackY2 = ((int) this.m_fY) + this._PlayerCol.GetAY2(iAni, iNowMotion);
            }
            int Attack = this._PlayerCol.GetATT(iAni, iNowMotion);
            if (Attack > 0) {
                if (this._PlayerAni.Ani_cnt == 0) {
                    EnemyManager.GetInstance().SetDamageFlag();
