package net.daum.mobilead;

public class AdConfig {
    public static final String ACTION_BANNER = "_b";
    public static final String ACTION_CALL = "_c";
    public static final String ACTION_HTML = "_l";
    public static final String ACTION_MARKET = "_a";
    public static final String ACTION_URL = "_w";
    private static final String SDK_VERSION = "1.3.1";
    private static String mClientId = null;
    private static String OUTPUT_TYPE = "xml";
    public static final String TEST_EMULATOR = "Unknown DeviceID";
    private static String[] mTestDeviceList = {TEST_EMULATOR};
    private static String mTestAction = null;

    private static void checkApplicationInfo(Context context) {
        String pubid;
        if (mClientId == null) {
            PackageManager packMan = context.getPackageManager();
            try {
                ApplicationInfo targetAppInfo = packMan.getApplicationInfo(context.getPackageName(), 128);
                if (targetAppInfo.metaData != null && (pubid = targetAppInfo.metaData.getString("MOBILEAD_CLIENT_ID")) != null && pubid.length() > 0) {
                    mClientId = pubid;
                }
            } catch (PackageManager.NameNotFoundException e) {
            }
        }
    }

    private static String getDeviceUID(Context context) {
        String buf = Settings.System.getString(context.getContentResolver(), "android_id");
        if (buf == null) {
            return TEST_EMULATOR;
        }
        return buf;
    }

    public static HashMap<String, Object> makeAdParams(MobileAdView view) throws UnsupportedEncodingException, MobileAdSDKException {
        HashMap<String, Object> adparams = new HashMap<>();
        checkApplicationInfo(view.getContext());
        if (getClientId() == null) {
            throw new MobileAdSDKException(MobileAdSDKError.AD_DOWNLOAD_ERROR_UNKNOWN_CLIENTID);
        }
        adparams.put("client", getClientId());
        adparams.put("ct", "AA");
        adparams.put("test", isTestDevice(view.getContext()) ? "y" : "n");
        adparams.put("dev", URLEncoder.encode(Build.MODEL, "UTF8"));
        adparams.put("osver", URLEncoder.encode(Build.VERSION.RELEASE, "UTF8"));
        adparams.put("output", URLEncoder.encode(OUTPUT_TYPE, "UTF8"));
        if (isTestDevice(view.getContext())) {
            adparams.put("q", mTestAction);
        }
        adparams.put("oe", "utf8");
        adparams.put("ie", "utf8");
        adparams.put("sdkver", URLEncoder.encode(SDK_VERSION, "UTF8"));
        if (view.getWidth() != 0 || view.getHeight() != 0) {
            adparams.put("w", Integer.valueOf(view.getWidth()));
            adparams.put("h", Integer.valueOf(view.getHeight()));
        }
        return adparams;
    }

    public static void setTestAction(String testAction) {
        mTestAction = testAction;
    }

    public static String getTestAction() {
        return mTestAction;
    }

    public static void setTestDevice(String[] devList) {
        mTestDeviceList = devList;
    }

    public static boolean isTestDevice(Context context) {
        boolean ret = false;
        if (AdCommon.get("appid") != null) {
            if (AdCommon.get("test").equals("true")) {
                return true;
            }
            return false;
        }
        if (mTestDeviceList == null || mTestDeviceList.length <= 0) {
            return false;
        }
        String uid = getDeviceUID(context);
        int i = 0;
        while (i < mTestDeviceList.length) {
            ret = mTestDeviceList[i].equals(uid);
            if (ret) {
                i = mTestDeviceList.length;
            }
            i++;
        }
        return ret;
    }

    public static void setClientId(String clientId) {
        if (clientId != null && clientId.length() <= 0) {
            mClientId = null;
        } else {
            mClientId = clientId;
        }
    }

    public static String getClientId() {
        return mClientId;
    }
}

