public class AdProtocolHandler {
    public MobileAd requestAd(String url, Map<String, Object> params, String userAgent) throws MobileAdSDKException {
        String uri = url + "?" + ((Object) makeAdsParams(params));
        ArrayList<MobileAd> arrAds = new ArrayList<>();
        AdHttpContext adHttpContext = new AdHttpContext(arrAds, userAgent);
        AdCommon.debug("AdProtocolHandler", uri);
        adHttpContext.requestAds(uri);
        if (adHttpContext.httpResponseResult() == 200) {
            if (arrAds.size() > 0) {
                MobileAd ad = arrAds.get(0);
                if (ad == null) {
                    throw new MobileAdSDKException(MobileAdSDKError.AD_DOWNLOAD_ERROR_NOAD);
                }
                if (adHttpContext.currentProcess() == AdHttpContext.PROCESS_DOWNLOAD_AD.PROCESS_DOWNLOAD_AD_FINISH) {
                    return ad;
                }
                throw new MobileAdSDKException(MobileAdSDKError.AD_DOWNLOAD_ERROR_INVALIDAD, ad.curl);
            }
            throw new MobileAdSDKException(MobileAdSDKError.AD_DOWNLOAD_ERROR_NOAD);
        }
        throw new MobileAdSDKException(MobileAdSDKError.AD_DOWNLOAD_ERROR_HTTPFAILED);
    }

    private StringBuilder makeAdsParams(Map<String, Object> params) {
        StringBuilder sb = new StringBuilder();
        for (String name : params.keySet()) {
            Object value = params.get(name);
            if (value != null) {
                if (sb.length() > 0) {
                    sb.append('&');
                }
                sb.append(name);
                sb.append('=');
                sb.append(value.toString());
            }
        }
        return sb;
    }
}

